#!/usr/bin/env python3
"""
Find duplicate files in a directory tree by SHA-256 hash.

Usage:
    python find_duplicates.py /path/to/directory

If no directory is given, it defaults to the current directory.
"""

import argparse
import hashlib
import os
import sys
from collections import defaultdict


def sha256_file(path: str, chunk_size: int = 1024 * 1024) -> str | None:
    """
    Return the SHA-256 hex digest of a file, or None if it cannot be read.
    """
    digest = hashlib.sha256()

    try:
        with open(path, "rb") as f:
            while True:
                chunk = f.read(chunk_size)
                if not chunk:
                    break
                digest.update(chunk)
    except OSError as exc:
        print(f"error: cannot read {path}: {exc}", file=sys.stderr)
        return None

    return digest.hexdigest()


def find_duplicate_groups(root: str) -> list[list[str]]:
    """
    Walk the directory tree rooted at `root` and return groups of duplicate files.

    Files are first grouped by size, then files with the same size are hashed.
    This avoids hashing files that cannot possibly be duplicates.
    """
    files_by_size = defaultdict(list)

    for dirpath, _, filenames in os.walk(root, followlinks=False):
        for filename in filenames:
            path = os.path.join(dirpath, filename)

            # Skip symbolic links so we do not accidentally follow them.
            if os.path.islink(path):
                continue

            try:
                size = os.path.getsize(path)
            except OSError as exc:
                print(f"error: cannot stat {path}: {exc}", file=sys.stderr)
                continue

            files_by_size[size].append(path)

    files_by_hash = defaultdict(list)

    for size, paths in files_by_size.items():
        # If only one file has this size, it cannot have a duplicate.
        if len(paths) < 2:
            continue

        for path in paths:
            file_hash = sha256_file(path)
            if file_hash is not None:
                files_by_hash[file_hash].append(path)

    duplicate_groups = [
        sorted(paths)
        for paths in files_by_hash.values()
        if len(paths) > 1
    ]

    return duplicate_groups


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Find duplicate files in a directory tree by SHA-256 hash."
    )
    parser.add_argument(
        "directory",
        nargs="?",
        default=".",
        help="Directory to scan. Defaults to the current directory.",
    )
    args = parser.parse_args()

    root = os.path.abspath(args.directory)

    if not os.path.isdir(root):
        print(f"error: {root} is not a directory", file=sys.stderr)
        return 1

    duplicate_groups = find_duplicate_groups(root)

    if not duplicate_groups:
        print("No duplicate files found.")
        return 0

    for group in duplicate_groups:
        print("Duplicate group:")
        for path in group:
            print(f"  {path}")
        print()

    print(f"Found {len(duplicate_groups)} duplicate group(s).")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
```

